components-loginpage--default.expression:
() => {
  const stage = document.querySelector('[data-login-stage]');
  const rows = [...document.querySelectorAll('[data-login-row]')];
  const panel = stage?.querySelector('[data-login-panel="' + stage.dataset.loginActive + '"]');
  return (!stage || (panel && stage.dataset.loginPhase === 'visible' && Math.abs(stage.getBoundingClientRect().height - panel.getBoundingClientRect().height) < 0.1)) && rows.every(row => row.dataset.loginRow === 'visible' && Math.abs(row.getBoundingClientRect().height - (row.inert ? 0 : row.firstElementChild.getBoundingClientRect().height)) < 0.1);
}

